fn shift_by_first(v: &mut Vec<i32>) {
    let delta = v[0];
    for x in v.iter_mut() {
        *x += delta;
    }
}

fn shift_by_first_v2(v: &mut Vec<i32>) {
    let first = &v[0];
    for x in v.iter_mut() {
        *x += *first;
    }
}

fn main() {
    let mut v = vec![10, 20, 30];
    shift_by_first_v2(&mut v);
    println!("{:?}", v);
}
